@SpringBootTest(properties={
        "spring.cloud.service-registry.auto-registration.enabled=false",
        "spring.datasource.url=jdbc:h2:mem:alert-recovery;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE",
        "spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=",
        "spring.sql.init.mode=always","spring.sql.init.schema-locations=classpath:schema-test.sql",
        "flowdesk.alert.ticket-result.entry.enabled=true","flowdesk.alert.ticket-result.consumer.enabled=false","FLOWDESK_ALERT_DB_PASSWORD="
})
@AutoConfigureMockMvc
class AlertRecoveryApiIntegrationTest{
    private static final UUID TENANT=UUID.fromString("51111111-1111-4111-8111-111111111111"),ADMIN=UUID.fromString("52222222-2222-4222-8222-222222222222");private static final KeyPair KEY=newKeyPair();private static final JwtIssuer ISSUER=new JwtIssuer(KEY.getPrivate(),"flowdesk-iam-service","flowdesk-api","flowdesk-internal",900,300);
    @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;
    @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("flowdesk.security.jwt.public-key-pem",AlertRecoveryApiIntegrationTest::publicKeyPem);r.add("flowdesk.security.cursor-token.hmac-key",()->Base64.getEncoder().encodeToString("0123456789abcdef0123456789abcdef".getBytes(StandardCharsets.UTF_8)));}
    @BeforeEach void reset(){for(String table:new String[]{"message_recovery","audit_record","inbox_message","outbox_event","incident_ticket_link","incident","alert_event","webhook_nonce","monitoring_integration"})jdbc.execute("DELETE FROM "+table);}

    @Test void replaysCreateOutboxButNeverDowngradesEstablishedLinkForRecoveryOutbox()throws Exception{Seed create=seedIncident("create","RECOVERY_REQUIRED",null);UUID createOutbox=seedOutbox(create,AlertEventContract.TICKET_CREATE_REQUESTED.contractRef());UUID createRecovery=seedRecovery("OUTBOX",createOutbox,create.createIntent(),8);String auth="Bearer "+token();mvc.perform(get("/api/v1/alert-message-recoveries/"+createRecovery).header("Authorization",auth)).andExpect(status().isOk()).andExpect(header().string("ETag","\"lv:0\""));mvc.perform(post("/api/v1/alert-message-recoveries/"+createRecovery+"/replays").header("Authorization",auth).header("Idempotency-Key","alert-replay-key-0001").header("If-Match","\"lv:0\"").contentType("application/json").content("{\"reason\":\"operator verified broker availability\"}")).andExpect(status().isAccepted()).andExpect(jsonPath("$.data.state").value("REPLAYING")).andExpect(jsonPath("$.data.replayCount").value(1));assertThat(jdbc.queryForObject("SELECT status FROM outbox_event WHERE outbox_id=?",String.class,AlertRepository.bytes(createOutbox))).isEqualTo("PENDING");assertThat(jdbc.queryForObject("SELECT status FROM incident_ticket_link WHERE incident_id=?",String.class,AlertRepository.bytes(create.incident()))).isEqualTo("REQUESTED");
        UUID ticket=UUID.randomUUID();Seed recovered=seedIncident("recovered","ESTABLISHED",ticket);UUID recoveryOutbox=seedOutbox(recovered,AlertEventContract.INCIDENT_RECOVERED.contractRef());UUID recoveryFact=seedRecovery("OUTBOX",recoveryOutbox,AlertIdempotencyCodec.derivedKey(AlertEventContract.INCIDENT_RECOVERED.intentNamespace(),TENANT,recovered.incident()),8);mvc.perform(post("/api/v1/alert-message-recoveries/"+recoveryFact+"/replays").header("Authorization",auth).header("Idempotency-Key","alert-replay-key-0002").header("If-Match","\"lv:0\"").contentType("application/json").content("{\"reason\":\"retry timeline delivery only\"}")).andExpect(status().isAccepted());assertThat(jdbc.queryForObject("SELECT status FROM incident_ticket_link WHERE incident_id=?",String.class,AlertRepository.bytes(recovered.incident()))).isEqualTo("ESTABLISHED");assertThat(AlertRepository.uuid(jdbc.queryForObject("SELECT ticket_id FROM incident_ticket_link WHERE incident_id=?",byte[].class,AlertRepository.bytes(recovered.incident())))).isEqualTo(ticket);}

    @Test void controlledInboxReplayUsesSameAuthoritativeResultEntryAndResolves()throws Exception{Seed seed=seedIncident("inbox","REQUESTED",null);UUID ticket=UUID.randomUUID(),message=UUID.randomUUID();byte[] resultIntent=AlertIdempotencyCodec.derivedKey(AlertEventContract.TICKET_ESTABLISHED.intentNamespace(),TENANT,seed.incident());String body="{\"schemaVersion\":\"1\",\"incidentId\":\""+seed.incident()+"\",\"createTicketIntentKey\":\""+HexFormat.of().formatHex(seed.createIntent())+"\",\"ticketId\":\""+ticket+"\",\"establishedAt\":\"2026-08-26T03:00:00.000000Z\"}";byte[] bytes=body.getBytes(StandardCharsets.UTF_8);UUID inbox=UUID.randomUUID();Instant now=Instant.parse("2026-08-26T03:00:00Z");jdbc.update("INSERT INTO inbox_message(tenant_id,inbox_id,producer_service,message_id,business_intent_key,contract_ref,contract_version,body_sha256,body_bytes,correlation_id,causation_id,occurred_at,status,result_type,result_id,attempt_count,last_error_code,first_received_at,last_attempt_at,processed_at,lock_version,created_at,updated_at,updated_by_type,updated_by_id) VALUES(?,?,?,?,?,?,1,?,?,?,?,?,'RECOVERY_REQUIRED',NULL,NULL,6,'BROKER_RETRIES_EXHAUSTED',?,?,NULL,0,?,?,'SERVICE',NULL)",AlertRepository.bytes(TENANT),AlertRepository.bytes(inbox),AlertEventContract.TICKET_ESTABLISHED.producer(),AlertRepository.bytes(message),resultIntent,AlertEventContract.TICKET_ESTABLISHED.contractRef(),AlertIdempotencyCodec.sha256(bytes),bytes,AlertRepository.bytes(UUID.randomUUID()),null,Timestamp.from(now),Timestamp.from(now),Timestamp.from(now),Timestamp.from(now),Timestamp.from(now));UUID recovery=seedRecovery("INBOX",inbox,resultIntent,6);mvc.perform(post("/api/v1/alert-message-recoveries/"+recovery+"/replays").header("Authorization","Bearer "+token()).header("Idempotency-Key","alert-replay-key-0003").header("If-Match","\"lv:0\"").contentType("application/json").content("{\"reason\":\"replay accepted Ticket result\"}")).andExpect(status().isAccepted());await("SELECT state FROM message_recovery WHERE recovery_id=?",AlertRepository.bytes(recovery),"RESOLVED");assertThat(jdbc.queryForObject("SELECT status FROM inbox_message WHERE inbox_id=?",String.class,AlertRepository.bytes(inbox))).isEqualTo("PROCESSED");assertThat(jdbc.queryForObject("SELECT status FROM incident_ticket_link WHERE incident_id=?",String.class,AlertRepository.bytes(seed.incident()))).isEqualTo("ESTABLISHED");}

    private Seed seedIncident(String suffix,String status,UUID ticket){Instant now=Instant.parse("2026-08-26T01:00:00Z");UUID integration=UUID.randomUUID(),event=UUID.randomUUID(),incident=UUID.randomUUID();byte[] create=AlertIdempotencyCodec.derivedKey(AlertEventContract.TICKET_CREATE_REQUESTED.intentNamespace(),TENANT,incident);jdbc.update("INSERT INTO alert_event(tenant_id,alert_event_id,integration_id,external_event_id,event_type,fingerprint,alert_cycle_ref,occurred_at,received_at,disposition,incident_id,raw_body_sha256,raw_body_ref,raw_body_ciphertext,summary,correlation_id,created_at,created_by_type,created_by_id) VALUES(?,?,?,?,'FIRING',?,'cycle',?,?,'APPLIED',?,?,NULL,NULL,'seed',?,?,'INTEGRATION',?)",AlertRepository.bytes(TENANT),AlertRepository.bytes(event),AlertRepository.bytes(integration),"evt-"+suffix,"fp-"+suffix,Timestamp.from(now),Timestamp.from(now),AlertRepository.bytes(incident),new byte[32],AlertRepository.bytes(UUID.randomUUID()),Timestamp.from(now),AlertRepository.bytes(integration));jdbc.update("INSERT INTO incident(tenant_id,incident_id,fingerprint,generation_no,status,first_event_id,last_event_id,event_count,opened_at,last_event_at,recovered_at,recovery_event_id,recovery_review_state,summary,lock_version,created_at,created_by_type,created_by_id,updated_at,updated_by_type,updated_by_id) VALUES(?,?,?,1,'ACTIVE',?,?,1,?,?,NULL,NULL,'NONE','seed',0,?,'INTEGRATION',?,?,'SERVICE',NULL)",AlertRepository.bytes(TENANT),AlertRepository.bytes(incident),"fp-"+suffix,AlertRepository.bytes(event),AlertRepository.bytes(event),Timestamp.from(now),Timestamp.from(now),Timestamp.from(now),AlertRepository.bytes(integration),Timestamp.from(now));boolean established="ESTABLISHED".equals(status);jdbc.update("INSERT INTO incident_ticket_link(tenant_id,incident_id,create_ticket_intent_key,status,ticket_id,requested_at,established_at,recovery_required_at,recovery_reason_code,retry_count,last_attempt_at,lock_version,created_at,created_by_type,created_by_id,updated_at,updated_by_type,updated_by_id) VALUES(?,?,?,?,?,?,?,?,?,8,?,0,?,'SERVICE',NULL,?,'SERVICE',NULL)",AlertRepository.bytes(TENANT),AlertRepository.bytes(incident),create,status,AlertRepository.bytes(ticket),Timestamp.from(now),established?Timestamp.from(now):null,"RECOVERY_REQUIRED".equals(status)?Timestamp.from(now):null,"RECOVERY_REQUIRED".equals(status)?"BROKER_RESULT_UNKNOWN":null,Timestamp.from(now),Timestamp.from(now),Timestamp.from(now));return new Seed(incident,create);}
    private UUID seedOutbox(Seed seed,String contract){Instant now=Instant.parse("2026-08-26T02:00:00Z");UUID outbox=UUID.randomUUID(),message=UUID.randomUUID();byte[] body="{}".getBytes(StandardCharsets.UTF_8),intent=AlertEventContract.TICKET_CREATE_REQUESTED.contractRef().equals(contract)?seed.createIntent():AlertIdempotencyCodec.derivedKey(AlertEventContract.INCIDENT_RECOVERED.intentNamespace(),TENANT,seed.incident());jdbc.update("INSERT INTO outbox_event(tenant_id,outbox_id,message_id,publication_key,business_intent_key,aggregate_type,aggregate_id,contract_ref,contract_version,body_bytes,body_sha256,correlation_id,causation_id,status,attempt_count,next_attempt_at,locked_by,locked_at,last_error_code,broker_confirmed_at,lock_version,created_at,created_by_type,created_by_id,updated_at,updated_by_type,updated_by_id) VALUES(?,?,?,?,?,'INCIDENT',?,?,1,?,?,?,NULL,'RECOVERY_REQUIRED',8,?,NULL,NULL,'BROKER_RESULT_UNKNOWN',NULL,0,?,'SERVICE',NULL,?,'SERVICE',NULL)",AlertRepository.bytes(TENANT),AlertRepository.bytes(outbox),AlertRepository.bytes(message),AlertIdempotencyCodec.publicationKey(TENANT,message),intent,AlertRepository.bytes(seed.incident()),contract,body,AlertIdempotencyCodec.sha256(body),AlertRepository.bytes(UUID.randomUUID()),Timestamp.from(now),Timestamp.from(now),Timestamp.from(now));return outbox;}
    private UUID seedRecovery(String direction,UUID source,byte[] intent,int attempts){Instant now=Instant.parse("2026-08-26T02:00:00Z");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO message_recovery(tenant_id,recovery_id,direction,source_record_id,business_intent_key,state,attempt_count,next_attempt_at,last_error_code,last_error_summary,dead_lettered_at,recovery_required_at,replay_count,last_replayed_at,last_replayed_by_type,last_replayed_by_id,last_replay_reason,last_replay_correlation_id,resolved_at,lock_version,created_at,updated_at,updated_by_type,updated_by_id) VALUES(?,?,?,?,?,'OPEN',?,NULL,'BROKER_RESULT_UNKNOWN',NULL,NULL,?,0,NULL,NULL,NULL,NULL,NULL,NULL,0,?,?,'SERVICE',NULL)",AlertRepository.bytes(TENANT),AlertRepository.bytes(id),direction,AlertRepository.bytes(source),intent,attempts,Timestamp.from(now),Timestamp.from(now),Timestamp.from(now));return id;}
    private void await(String sql,byte[] id,String expected){for(int i=0;i<300;i++){if(expected.equals(jdbc.queryForObject(sql,String.class,id)))return;LockSupport.parkNanos(10_000_000L);}throw new AssertionError("Timed out waiting for "+expected);}private static String token(){return ISSUER.issueHuman(TENANT,ADMIN,Set.of(RoleCode.SERVICE_DESK_ADMIN),Set.of(PermissionCode.RECOVERY_READ_TENANT,PermissionCode.RECOVERY_REPLAY_TENANT)).token();}private static KeyPair newKeyPair(){try{return KeyPairGenerator.getInstance("RSA").generateKeyPair();}catch(Exception e){throw new IllegalStateException(e);}}private static String publicKeyPem(){String nl=System.lineSeparator();return "-----BEGIN PUBLIC KEY-----"+nl+Base64.getEncoder().encodeToString(KEY.getPublic().getEncoded())+nl+"-----END PUBLIC KEY-----";}private record Seed(UUID incident,byte[] createIntent){}
}
